        when(coverage.batch(anyList())).thenReturn(Map.of());when(references.options(anyList())).thenAnswer(call->phones.stream().filter(p->((List<?>)call.getArgument(0)).contains(p.get("phoneModelId"))).toList());
        upstream.put("phone",List.of());upstream.put("candidate",List.of());
