    @SuppressWarnings("unchecked") List<Map<String,Object>> content(Map<String,Object> page){return (List<Map<String,Object>>)page.get("content");}
    @Test void multipleCountryAndCandidateSourcesProduceOneStandardPhoneAndTrustedSnapshot(){upstream.put("phone",List.of(source(11,"iPhone 18 Pro","CN"),source(12,"IP 18 Pro","MX")));upstream.put("candidate",List.of(source(21,"iPhone 18 Pro","GLOBAL")));var page=service.page(new MarketWatchTypes.ModelQuery());assertThat(page.get("totalElements")).isEqualTo(1L);var row=content(page).get(0);assertThat(row.get("sourceCount")).isEqualTo(3);assertThat(row.get("countries")).isEqualTo(List.of("CN","GLOBAL","MX"));assertThat((List<?>)service.draftContext("phone:"+first).get("sources")).hasSize(3);}
    @Test void failureKeepsTheLastCompleteSnapshotAndRetryRecovers(){upstream.put("phone",List.of(source(11,"iPhone 18 Pro","CN")));service.refresh();doThrow(new BusinessException(50201,"不可用")).when(client).items(any());var failed=service.refresh();assertThat(failed.get("lastError")).isNotNull();assertThat(content(service.page(new MarketWatchTypes.ModelQuery()))).hasSize(1);assertThat(jdbc.queryForObject("select count(*) from plm_market_watch_source_projection where active",Long.class)).isEqualTo(1L);doAnswer(call->{org.springframework.util.MultiValueMap<String,String> q=call.getArgument(0);var rows=upstream.get(q.getFirst("kind"));return Map.of("content",rows,"totalElements",rows.size());}).when(client).items(any());assertThat(service.refresh().get("lastError")).isNull();}
    @Test void removedCandidatesDoNotBreakAStoredCrossSourceDraftContext(){upstream.put("candidate",List.of(source(21,"IP 18 Pro","CN")));service.refresh();upstream.put("candidate",List.of());service.refresh();assertThat(content(service.page(new MarketWatchTypes.ModelQuery()))).isEmpty();assertThat((List<?>)service.sourceContext("candidate",21,first).get("sources")).hasSize(1);}
    @Test void exactAliasCollisionRequiresManualSelectionWithConflictProtection(){phones.get(1).put("aliases",List.of("IP 18 Pro"));upstream.put("phone",List.of(source(11,"IP 18 Pro","CN")));service.refresh();var row=content(service.page(new MarketWatchTypes.ModelQuery())).get(0);assertThat(row.get("matchState")).isEqualTo("ambiguous");assertThatThrownBy(()->service.draftContext(row.get("rowKey").toString())).isInstanceOf(BusinessException.class);service.link("phone",11,new MarketWatchTypes.LinkPhoneModel(first,null,null),null);assertThatThrownBy(()->service.link("phone",11,new MarketWatchTypes.LinkPhoneModel(second,null,"更正"),null)).isInstanceOf(BusinessException.class).hasMessageContaining("其他人修改");assertThat(service.sourceContext("phone",11,first).get("phoneModelId")).isEqualTo(first);}
    @Test void manualAssociationSurvivesAnIdenticalRefreshButSourceIdentityChangeIsRechecked(){upstream.put("phone",List.of(source(11,"Unknown","CN")));service.refresh();service.link("phone",11,new MarketWatchTypes.LinkPhoneModel(first,null,null),null);service.refresh();assertThat(content(service.page(new MarketWatchTypes.ModelQuery())).get(0).get("phoneModelId")).isEqualTo(first);upstream.put("phone",List.of(source(11,"iPhone 18 Pro Max","CN")));service.refresh();assertThat(content(service.page(new MarketWatchTypes.ModelQuery())).get(0).get("phoneModelId")).isEqualTo(second);}
    @Test void coverageFilteringAndCountsRunAcrossAllRowsBeforePagination(){upstream.put("phone",List.of(source(11,"iPhone 18 Pro","CN"),source(12,"iPhone 18 Pro Max","MX")));when(coverage.batch(anyList())).thenReturn(Map.of(second,List.of(Map.of("productLineId",1L,"productLineName","超队","state","making","states",List.of("making"),"applications",List.of(),"molds",List.of()))));var q=new MarketWatchTypes.ModelQuery();q.setSize(1);q.setCoverageState("making");var page=service.page(q);assertThat(page.get("totalElements")).isEqualTo(1L);assertThat(content(page).get(0).get("phoneModelId")).isEqualTo(second);assertThat(((Map<?,?>)((Map<?,?>)page.get("stats")).get("states")).get("making")).isEqualTo(1L);assertThat(((Map<?,?>)page.get("stats")).get("total")).isEqualTo(1);}
    @Test @SuppressWarnings("unchecked") void opportunityCountsAndStyleScopeUseTheSameRowsBeforePagination(){
        upstream.put("phone",List.of(source(11,"iPhone 18 Pro","CN"),source(12,"iPhone 18 Pro Max","MX"),source(13,"Unknown","CN")));
        long line=line();when(coverage.batch(anyList())).thenReturn(Map.of(second,List.of(Map.of("productLineId",line,"productLineName","已有款式","state","catalogued","states",List.of("catalogued"),"products",List.of(Map.of("productId",9L,"historicalSkuEvidence",true)),"applications",List.of(),"molds",List.of()))));
        var q=new MarketWatchTypes.ModelQuery();q.setSize(1);q.setOpportunityView("applied");var page=service.page(q);assertThat(page.get("totalElements")).isEqualTo(1L);assertThat(content(page).get(0).get("phoneModelId")).isEqualTo(first);
        var counts=(Map<String,Long>)((Map<?,?>)page.get("stats")).get("opportunities");assertThat(counts).containsEntry("applied",1L).containsEntry("partially_molded",1L).containsEntry("all",3L);
        q.setOpportunityView("needs_confirmation");assertThat(service.page(q).get("totalElements")).isEqualTo(1L);assertThat(((Map<?,?>)service.summary(q)).get("opportunities")).isEqualTo(counts);
        long other=jdbc.queryForObject("select product_id from plm_product where product_type='product_line' and sales_status='on_sale' and deleted_flag=0 and product_id<>? limit 1",Long.class,line);q.setOpportunityView("to_apply");q.setProductLineId(other);assertThat(service.page(q).get("totalElements")).isEqualTo(2L);
        q.setProductLineId(line);assertThat(service.page(q).get("totalElements")).isEqualTo(1L);q.setMatchState("unmatched");q.setOpportunityView("needs_confirmation");var unmatched=service.page(q);assertThat(unmatched.get("totalElements")).isEqualTo(1L);assertThat(((Map<?,?>)unmatched.get("stats")).get("total")).isEqualTo(1);
    }
    @Test void crawlerSwitchDoesNotDisableCachedOpportunitiesAndNeverAttemptsAPull(){upstream.put("phone",List.of(source(11,"iPhone 18 Pro","CN")));service.refresh();when(client.enabled()).thenReturn(false);clearInvocations(client);assertThat(content(service.page(new MarketWatchTypes.ModelQuery()))).hasSize(1);verify(client,never()).items(any());assertThatThrownBy(service::refresh).hasMessageContaining("仍可查看缓存");}
