    @Test @SuppressWarnings("unchecked") void realCoverageUsesEachPhoneApplicableSetsAndPreservesDifferentOriginalCodes() throws Exception {
        applicationSchema();long a=coveragePhone(),b=coveragePhone(),line=line(),item=archive(line),sa=set(item,1),sb=set(item,2);member(item,a,sa);member(item,b,sb);
        for(String part:List.of("PC","TPU")){jdbc.update("insert into plm_collaboration_mold_part(mold_set_id,part_type,physical_status,original_mold_code) values(?,?,'confirmed',?)",sa,part,part.equals("PC")?"MHA001144":"MHA011144");jdbc.update("insert into plm_collaboration_mold_part(mold_set_id,part_type,physical_status,original_mold_code) values(?,?,'making',?)",sb,part,part.equals("PC")?"MHA001144":"MHA011144");}
        var real=new PhoneModelCoverageService(jdbc,new PilotAccessService(jdbc,new ObjectMapper()));var result=real.batch(List.of(a,b));var first=result.get(a).get(0);var second=result.get(b).get(0);
        assertThat(first.get("state")).isEqualTo("reusable");assertThat(second.get("state")).isEqualTo("making");assertThat(((List<Map<String,Object>>)first.get("molds")).get(0).get("moldSetId")).isEqualTo(sa);assertThat(((List<Map<String,Object>>)second.get("molds")).get(0).get("moldSetId")).isEqualTo(sb);
    }
