    @Test @SuppressWarnings("unchecked") void legacyProjectArchiveLinkDoesNotGuessAllItsSetsFitThePhone() throws Exception {
        applicationSchema();long phone=coveragePhone(),line=line(),item=archive(line);set(item,1);set(item,2);
        long project=jdbc.queryForObject("insert into plm_product(product_id,product_code,product_name,product_type,parent_product_id,phone_model_member_id,status,version_no,created_by,updated_by) values(?,?,?,'model_variant',?,?,'developing','A','it','it') returning product_id",Long.class,UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE,"IT-"+UUID.randomUUID(),"IT-project",line,phone);jdbc.update("insert into plm_collaboration_item_project(item_id,project_id,linked_by) values(?,?,'it')",item,project);
        var result=new PhoneModelCoverageService(jdbc,new PilotAccessService(jdbc,new ObjectMapper())).batch(List.of(phone)).get(phone).get(0);assertThat(result.get("state")).isEqualTo("catalogued");assertThat((List<String>)result.get("states")).contains("needs_review");var molds=(List<Map<String,Object>>)result.get("molds");assertThat(molds).hasSize(1);assertThat(molds.get(0).get("moldSetId")).isNull();assertThat(molds.get(0).get("reusable")).isEqualTo(false);assertThat(molds.get(0)).containsEntry("registeredSets",2L).containsEntry("hasRegisteredSets",true);assertThat((List<Map<String,Object>>)molds.get(0).get("reviewReasons")).singleElement().satisfies(reason->assertThat(reason).containsEntry("action","select_set"));
    }
