    @Test @SuppressWarnings("unchecked") void historyMigrationInitializesOnlyUniqueAnchorsAndAuditsWithoutCreatingMoldsOrChangingSku() throws Exception {
        applicationSchema();String name="History-"+UUID.randomUUID();long brand=jdbc.queryForObject("insert into plm_phone_brand(name,created_by,updated_by) values(?,'it','it') returning id",Long.class,name);
        long code=historyCode(name+" X11 5G"),duplicate=historyCode(name+" X12 4G");historyCode(name+"  X12 4G");historyCode(name+" X13 Agujero fino");historyCode(name+" X14/X15");String value=jdbc.queryForObject("select code_value from plm_code_item where code_item_id=?",String.class,code);
        long project=historyProject(value,"X11 5G","model_variant"),sku=historyProject(value,"X11 5G","sku");
        long application=jdbc.queryForObject("insert into plm_mold_application(process_code,model,phone_code_item_id,created_by,updated_by) values('it','X11 5G',?,'it','it') returning application_id",Long.class,code);
        long codesBefore=jdbc.queryForObject("select count(*) from plm_code_item",Long.class),setsBefore=jdbc.queryForObject("select count(*) from plm_collaboration_mold_set",Long.class),compatBefore=jdbc.queryForObject("select count(*) from plm_collaboration_phone_member",Long.class);String expensesBefore=costSnapshot();
        var outcome=new db.migration.V20261014_1720__phone_identity_history().migrate(jdbc);long phone=jdbc.queryForObject("select id from plm_phone_model_member where code_item_id=?",Long.class,code);
        assertThat(jdbc.queryForObject("select phone_model_member_id from plm_product where product_id=?",Long.class,project)).isEqualTo(phone);assertThat(jdbc.queryForObject("select phone_model_member_id from plm_product where product_id=?",Long.class,sku)).isNull();assertThat(jdbc.queryForObject("select phone_model_id from plm_mold_application where application_id=?",Long.class,application)).isEqualTo(phone);
        assertThat(jdbc.queryForObject("select count(*) from plm_phone_model_member where code_item_id=?",Long.class,duplicate)).isZero();assertThat(jdbc.queryForObject("select model from plm_product where product_id=?",String.class,project)).isEqualTo("X11 5G");
        assertThat(jdbc.queryForObject("select count(*) from plm_code_item",Long.class)).isEqualTo(codesBefore);assertThat(jdbc.queryForObject("select count(*) from plm_collaboration_mold_set",Long.class)).isEqualTo(setsBefore);assertThat(jdbc.queryForObject("select count(*) from plm_collaboration_phone_member",Long.class)).isEqualTo(compatBefore);assertThat(costSnapshot()).isEqualTo(expensesBefore);
        assertThat(jdbc.queryForObject("select count(*) from plm_operation_log where business_type='PHONE_IDENTITY_HISTORY' and business_id='20261014.1720'",Long.class)).isGreaterThan(0);assertThat((List<?>)outcome.get("created")).isNotEmpty();long phonesBefore=jdbc.queryForObject("select count(*) from plm_phone_model_member",Long.class);var repeated=new db.migration.V20261014_1720__phone_identity_history().migrate(jdbc);assertThat((List<?>)repeated.get("created")).isEmpty();assertThat(jdbc.queryForObject("select count(*) from plm_phone_model_member",Long.class)).isEqualTo(phonesBefore);
    }
